use serde::{Deserialize,Serialize}; use super::{error::{AdmissionError,AdmissionErrorKind,Result},scope::Scope};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq,Hash)] pub enum Capability{Observe,Select,Construct,Actuate,Publish}
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct Grant{pub principal:String,pub capability:Capability,pub scope:Scope,pub expires_epoch:Option<u64>}
#[derive(Clone,Debug,Default,Serialize,Deserialize)] pub struct AuthoritySet{pub grants:Vec<Grant>}
impl AuthoritySet{pub fn allows_at(&self,p:&str,c:&Capability,repo:&str,path:&str,epoch:u64)->bool{self.grants.iter().any(|g|g.principal==p&&&g.capability==c&&g.scope.contains(repo,path)&&g.expires_epoch.map(|e|epoch<=e).unwrap_or(true))}pub fn require_at(&self,p:&str,c:Capability,repo:&str,path:&str,epoch:u64)->Result<()>{if self.allows_at(p,&c,repo,path,epoch){Ok(())}else{Err(AdmissionError::new(AdmissionErrorKind::AuthorityDenied,"authority.denied",format!("{p:?} lacks {c:?} on {repo}:{path}")).recoverable(true))}}pub fn effective<'a>(&'a self,p:&str,repo:&str,path:&str,epoch:u64)->Vec<&'a Grant>{let mut v:Vec<_>=self.grants.iter().filter(|g|g.principal==p&&g.scope.contains(repo,path)&&g.expires_epoch.map(|e|epoch<=e).unwrap_or(true)).collect();v.sort_by_key(|g|std::cmp::Reverse(g.scope.specificity()));v}}